<div class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">Nom singulier *</label><input class="form-control singular" maxlength="100" value="<?=htmlspecialchars($r['label_singular'])?>"></div><div class="col-md-4"><label class="form-label">Nom pluriel *</label><input class="form-control plural" maxlength="100" value="<?=htmlspecialchars($r['label_plural'])?>"></div><div class="col-md-2"><label class="form-label">Ordre</label><input type="number" class="form-control order" min="0" max="999" value="<?=(int)$r['sort_order']?>"></div><div class="col-md-2"><div class="host-config-preview"><small class="text-muted d-block">Menu</small><strong class="preview"><?=htmlspecialchars($r['label_plural'])?></strong></div></div></div>
