<script>document.addEventListener('DOMContentLoaded',()=>{const BASE_URL='<?=BASE_URL?>',CSRF='<?=htmlspecialchars($_SESSION['csrf'],ENT_QUOTES)?>';document.querySelectorAll('.host-config-card').forEach(card=>{const code=card.dataset.code,s=card.querySelector('.singular'),p=card.querySelector('.plural'),o=card.querySelector('.order'),preview=card.querySelector('.preview'),save=card.querySelector('.save-config'),toggle=card.querySelector('.toggle-config'),reset=card.querySelector('.reset-config');p.oninput=()=>preview.textContent=p.value||'—';async function send(extra={}){const fd=new FormData();fd.append('csrf',CSRF);fd.append('entity_code',code);fd.append('label_singular',s.value.trim());fd.append('label_plural',p.value.trim());fd.append('sort_order',o.value||0);fd.append('actif',extra.actif??(toggle?.dataset.next==='1'?0:1));if(extra.reset)fd.append('reset','1');return STAGIA.post(BASE_URL+'/actions/espace-hopital/structure-config-save.php',fd)}save.onclick=async()=>{STAGIA.loading(save,true);try{const r=await send({actif:toggle?.dataset.next==='0'?1:0});STAGIA.toast(r.message);setTimeout(()=>location.reload(),300)}catch(e){STAGIA.toast(e.message,'danger')}finally{STAGIA.loading(save,false)}};if(toggle)toggle.onclick=async()=>{const next=Number(toggle.dataset.next);if(!STAGIA.confirm(next?'Réactiver ce niveau ?':'Retirer ce niveau de la structure active ?'))return;try{const r=await send({actif:next});STAGIA.toast(r.message);setTimeout(()=>location.reload(),300)}catch(e){STAGIA.toast(e.message,'danger')}};reset.onclick=async()=>{if(!STAGIA.confirm('Restaurer le nom et le statut STAGIA ?'))return;try{const r=await send({reset:1});STAGIA.toast(r.message);setTimeout(()=>location.reload(),300)}catch(e){STAGIA.toast(e.message,'danger')}}})});</script>
